# -*- coding: utf-8 -*-
"""Penyelarasan RPP F.MEK: naskah gerbang asli dan latihan baru beralasan.

RPP D6 adalah kisi/pesanan, bukan naskah latihan yang telah diproduksi.
P7/P9 di sini adalah adaptasi baru; pilihan otomatis tidak menggantikan bukti
uraian, contoh buatan murid, serta profil per-proses pada gerbang guru.
"""
from copy import deepcopy
try:
    from . import lesson_newton_statika as _old
except ImportError:
    import lesson_newton_statika as _old


LABELS = ("Apa yang ditanyakan", "Formulasi", "Informasi distraktor",
          "Identifikasi data", "Substitusi", "Penyelesaian", "Kesimpulan")


def _steps(*parts):
    if len(parts) != 7:
        raise ValueError("Pembahasan memerlukan tujuh langkah konkret")
    return [f"{label}: {part}" for label, part in zip(LABELS, parts)]


def _q(indicator, prompt, options, answer, parts, *, level="C2", seconds=180, diagram=None):
    steps = _steps(*parts)
    item = {"indicator": indicator, "prompt": prompt, "kind": "choice", "label": "Pilih satu penjelasan yang paling tepat",
            "options": options, "answer": answer, "unit": "", "level": level, "seconds": seconds,
            "steps": steps, "explain": steps[-2] + " " + steps[-1]}
    if diagram:
        item["diagram"] = diagram
    return item


def _n(indicator, prompt, answer, unit, parts, *, label="Nilai yang diminta", level="C4", seconds=240, tol=0.05, diagram=None):
    steps = _steps(*parts)
    item = {"indicator": indicator, "prompt": prompt, "kind": "num", "label": label,
            "answer": answer, "unit": unit, "tol": tol, "level": level, "seconds": seconds,
            "steps": steps, "explain": steps[-2] + " " + steps[-1]}
    if diagram:
        item["diagram"] = diagram
    return item


