            _q("s1", f"Beban {W:g} N bekerja vertikal pada rak. Tim menggesernya dari 0,60 m menjadi 0,30 m dari engsel, lalu berkata 'beratnya turun separuh'. Pilih koreksi yang benar.",
               ["Berat tetap; besar momen bebannya yang menjadi separuh karena lengan gaya berkurang separuh.", "Berat dan momen keduanya selalu tetap ketika beban bergeser.", "Momen menjadi dua kali karena beban mendekati engsel."], 0,
               ("Menentukan besaran yang berubah ketika letak beban berubah.", "Untuk gaya vertikal pada rak mendatar, besar momen adalah W x.", "Menggeser benda tidak mengubah massa atau gravitasi dalam model ini.", f"W = {W:g} N, x1 = 0,60 m, x2 = 0,30 m.", f"|τ1| = {W:g} × 0,60; |τ2| = {W:g} × 0,30.", f"Momen berubah dari {W*.6:g} menjadi {W*.3:g} N·m, sedangkan W tetap {W:g} N.", "Pernyataan tentang berat ditolak; tuntutan momen penahanlah yang berkurang."), level="C4", seconds=240),
            _n("s2", f"Linggis ringan bertumpu di antara tangan dan batu. Tangan menekan ke bawah {F:g} N pada lengan 1,50 m. Batu menekan linggis ke bawah pada lengan 0,25 m di sisi seberang. Pada ambang batu terangkat secara perlahan, berapa gaya tumpu ke atas pada linggis?", 7*F, "N",
               ("Mencari gaya tumpuan, sehingga gaya batu perlu ditentukan lebih dahulu.", "Στtumpu = 0 memberi F·ltangan = W·lbatu; ΣFy = 0 memberi N = F + W.", "Berat linggis diabaikan karena disebut ringan pada model; jangan menyamakan gaya di dua lengan.", f"F = {F:g} N, ltangan = 1,50 m, lbatu = 0,25 m; kedua gaya pada linggis berarah bawah.", f"W = {F:g} × 1,50/0,25; N = {F:g} + W.", f"W = {6*F:g} N; N = {7*F:g} N. Momen kedua sisi sama besar meskipun besar gayanya berbeda.", f"Gaya tumpu {7*F:g} N ke atas menyeimbangkan kedua gaya ke bawah; memakai Στ saja belum menghasilkan N."), label="Gaya tumpu", seconds=300),
            _q("s2", "Sebuah batang bebas menerima dua gaya berlawanan sama besar pada garis sejajar terpisah. Pusat massanya tidak dipercepat, tetapi batang mulai berputar. Manakah penjelasan yang konsisten?",
               ["ΣF = 0 tetapi Στ tidak nol; syarat translasi terpenuhi, syarat rotasi belum.", "ΣF pasti tidak nol karena semua gerak memerlukan resultan gaya.", "Batang melanggar Newton karena dua gaya yang seimbang tidak bisa menghasilkan akibat."], 0,
               ("Membedakan pemeriksaan translasi dan rotasi.", "Benda tegar setimbang statis memerlukan ΣF = 0 dan Στ = 0.", "Gerak rotasi tidak boleh dipakai sebagai bukti bahwa resultan gaya translasi tidak nol.", "Dua gaya sama besar berlawanan memiliki garis kerja terpisah, sehingga membentuk kopel.", "ΣF = F − F = 0; besar Στ = Fd dengan d tak nol.", "Kopel dapat memberi percepatan sudut tanpa mempercepat pusat massa. Tidak ada pertentangan karena dua persamaan memeriksa akibat berbeda.", "Gunakan kedua syarat, bukan hanya jumlah gaya."), level="C4", seconds=240),
