def make_questions(slug, stage, form=1):
    stage=str(stage).strip().upper()
    if not stage.startswith("P"):
        stage="P"+stage
    if isinstance(form, bool) or not isinstance(form, int) or form<1:
        raise ValueError("form harus bilangan bulat positif")
    if slug not in {"f-mek-1a", "f-mek-1b"}:
        raise KeyError(slug)
    if stage not in {"P7", "P9"}:
        return _old.make_questions(slug, stage, form)
    result=deepcopy((_newton if slug=="f-mek-1a" else _statika)(stage,form-1))
    for i,q in enumerate(result,1):
        q["id"]=f"rpp-{slug}-{stage.lower()}-f{form}-{i:02d}"
        if q["kind"]=="choice":
            shift=(form+i-1)%len(q["options"])
            q["options"]=q["options"][shift:]+q["options"][:shift]
            q["answer"]=(q["answer"]-shift)%len(q["options"])
    return result


